module ways_to_choose(\n    input [63:0] n,\n    input [63:0] k,\n    output reg [63:0] result\n);\n    reg [63:0] lower_bound;\n    reg [63:0] upper_bound;\n    reg [63:0] temp;\n\n    always @(*) begin\n        if (k > n)\n            lower_bound = k - n;\n        else\n            lower_bound = 64'd1;\n\n        temp = (k - 64'd1) >> 1;\n\n        if (temp < n)\n            upper_bound = temp;\n        else\n            upper_bound = n;\n\n        if (lower_bound <= upper_bound)\n            result = upper_bound - lower_bound + 64'd1;\n        else\n            result = 64'd0;\n    end\nendmodule